/* Foundry UI — Tailwind v4 theme bridge. Maps --fu-* system tokens to utilities
   (bg-fu-surface, text-fu-ink, border-fu-line, rounded-fu-md, shadow-fu-card …). */
@theme inline {
  --color-fu-page: var(--fu-page);
  --color-fu-surface: var(--fu-surface);
  --color-fu-raised: var(--fu-raised);
  --color-fu-sunken: var(--fu-sunken);
  --color-fu-hover: var(--fu-hover);
  --color-fu-line: var(--fu-line);
  --color-fu-line-strong: var(--fu-line-strong);
  --color-fu-ink: var(--fu-ink);
  --color-fu-body: var(--fu-body);
  --color-fu-muted: var(--fu-muted);
  --color-fu-faint: var(--fu-faint);
  --color-fu-accent: var(--fu-accent);
  --color-fu-accent-soft: var(--fu-accent-soft);
  --color-fu-accent-ink: var(--fu-accent-ink);
  --color-fu-series-2: var(--fu-series-2);
  --color-fu-series-3: var(--fu-series-3);
  --color-fu-series-4: var(--fu-series-4);
  --color-fu-positive: var(--fu-positive);
  --color-fu-positive-soft: var(--fu-positive-soft);
  --color-fu-negative: var(--fu-negative);
  --color-fu-negative-soft: var(--fu-negative-soft);
  --color-fu-warning: var(--fu-warning);
  --color-fu-warning-soft: var(--fu-warning-soft);
  --color-fu-positive-text: var(--fu-positive-text);
  --color-fu-negative-text: var(--fu-negative-text);
  --color-fu-warning-text: var(--fu-warning-text);
  --color-fu-accent-text: var(--fu-accent-text);
  --radius-fu-xs: var(--fu-radius-xs);
  --radius-fu-sm: var(--fu-radius-sm);
  --radius-fu-md: var(--fu-radius-md);
  --radius-fu-lg: var(--fu-radius-lg);
  --radius-fu-xl: var(--fu-radius-xl);
  --shadow-fu-card: var(--fu-shadow-card);
  --shadow-fu-overlay: var(--fu-shadow-overlay);
  --shadow-fu-button: var(--fu-shadow-button);
  --font-fu: var(--fu-font);
  --font-fu-mono: var(--fu-font-mono);
}

/* Loopo — tokens extracted from the Loopo dashboard (1440 design values).
   Light mode only (dark mode is planned for the first post-launch update). */
:root,
[data-system="loopo"] {
  --fu-font: var(--font-geist-sans, "Geist"), ui-sans-serif, system-ui, sans-serif;
  --fu-font-mono: var(--font-geist-mono, "Geist Mono"), ui-monospace, monospace;
  --fu-page: #f5f5f5;
  --fu-surface: #ffffff;
  --fu-raised: #fefefe;
  --fu-sunken: #fafafa;
  --fu-hover: #f4f4f5;
  --fu-line: #ececec;
  --fu-line-strong: #e1e1e1;
  --fu-ink: #202020;
  --fu-body: #2d2d2d;
  --fu-muted: #747474;
  --fu-faint: #a6a6a6;
  --fu-accent: #fd4b23;
  --fu-accent-soft: #fff1ed;
  --fu-accent-ink: #ffffff;
  --fu-accent-grad: linear-gradient(180deg, #fd6a48 0%, #fd4b23 100%);
  --fu-series-2: #4d98fe;
  --fu-series-3: #ff72ab;
  --fu-series-4: #f3c83d;
  --fu-positive: #18b170;
  --fu-positive-soft: #ebf8f2;
  --fu-negative: #e5484d;
  --fu-negative-soft: #fdeeee;
  --fu-warning: #d99a06;
  --fu-warning-soft: #fdf6e3;
  /* Text tones: pass WCAG AA (4.5:1+) on their soft backgrounds and on white. Fills keep the bright tones. */
  --fu-positive-text: #0f7d4f;
  --fu-negative-text: #c4282e;
  --fu-warning-text: #8a6000;
  --fu-accent-text: #c2361a;
  --fu-primary-grad: linear-gradient(180deg, #838383 0%, #2d2d2d 100%);
  --fu-radius-xs: 6px;
  --fu-radius-sm: 8px;
  --fu-radius-md: 10px;
  --fu-radius-lg: 14px;
  --fu-radius-xl: 22px;
  --fu-shadow-card: 0 1px 4px rgb(0 0 0 / 0.05);
  --fu-shadow-overlay: 0 16px 32px -12px rgb(13 13 18 / 0.12), 0 1px 2px rgb(13 13 18 / 0.05);
  --fu-shadow-button: 0 9px 8px rgb(0 0 0 / 0.04), inset 0 1px 0 rgb(255 255 255 / 0.18);
}
